// Router: nhan Message Envelope (spec ARCHITECTURE.md muc 3) tu Gateway.
// 07/09/2026: bo han /sync* + /sync_status + /db_status - da tach rieng sang
// Telebot_Admin_System.json (bot System rieng, admin dung). Bot thuong (qua Gateway) chi con:
// help / task / chitiet / free_text.
const items = $input.all();

function parseCommand(rawText) {
  let command = '';
  let params = '';
  if ((rawText || '').startsWith('/')) {
    const parts = rawText.trim().split(/\s+/);
    command = parts[0].toLowerCase();
    params = parts.slice(1).join(' ');
  } else {
    params = rawText || '';
  }
  return { command, params };
}

function computeRoute(command, params) {
  if (params.startsWith('chitiet_')) {
    return { route: 'chitiet', params: 'chitiet', taskId: params.replace('chitiet_', '').trim() };
  }
  if (command === '/task') return { route: 'task', params, taskId: null };
  if (command === '/help' || command === '/start') return { route: 'help', params, taskId: null };
  if (!command && params) return { route: 'free_text', params, taskId: null };
  return { route: 'unknown_command', params, taskId: null };
}

return items.map(it => {
  const env = it.json ?? {};
  const isCallback = env.kind === 'callback';
  const rawText = isCallback ? (env.callback?.data || '') : (env.text || '');

  let route, command = '', params = '', taskId = null;

  if (isCallback) {
    if (rawText.startsWith('chitiet_')) {
      route = 'chitiet'; taskId = rawText.replace('chitiet_', '').trim(); params = 'chitiet';
    } else {
      route = 'unknown_command'; params = rawText;
    }
  } else {
    const parsed = parseCommand(rawText);
    command = parsed.command;
    const r = computeRoute(parsed.command, parsed.params);
    route = r.route; params = r.params; taskId = r.taskId;
  }

  const legacyMessage = !isCallback ? {
    text: env.text || '',
    chat: { id: env.chat_id },
    message_id: env.raw?.message_id ?? null,
    from: { id: env.user_id, username: env.username }
  } : undefined;
  const legacyCallback = isCallback ? {
    id: env.callback?.id,
    data: env.callback?.data,
    message: { chat: { id: env.chat_id }, message_id: env.callback?.message_id }
  } : undefined;

  return {
    json: {
      route, command, params, taskId,
      chatId: env.chat_id,
      messageId: isCallback ? (env.callback?.message_id ?? null) : (env.raw?.message_id ?? null),
      isCallback,
      originalData: { ...env, message: legacyMessage, callback_query: legacyCallback }
    }
  };
});

const input = $json;
const helpText = `<b>\U0001F4D8 Danh sach lenh Telegram</b>\n\n` +
  `\U0001F449 <code>/task &lt;tu khoa&gt;</code> - Tim task\n` +
  `\U0001F449 <code>/task chitiet_&lt;id&gt;</code> - Chi tiet task\n\n` +
  `\U0001F4CC <i>Vi du:</i>\n<code>/task linh nhi</code>`;
return [{ json: { ...input, text: helpText, parse_mode: "HTML" } }];

const raw = ($json.params || '').trim();
const normalize = (s) => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/\u0111/g, 'd').replace(/\u0110/g, 'D').toLowerCase();
return [{ json: { ...$json, originalText: raw, originalText_khong_dau: normalize(raw) } }];

const chatId = $('Phân tích lệnh').first().json.chatId;
const searchText = $('Prepare Search').first().json.originalText || '';
const all = $input.all().map(i => i.json).filter(t => t && t.id); // loc bo item rong (alwaysOutputData placeholder)

const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cleanLink = (l) => (l || '').replace(/^'+|'+$/g, '').replace(/[{}]/g, '').trim();
const botUsername = $('⚙️ Config').first().json.botUsername;

if (all.length === 0) {
  return [{ json: { chatId,
    text: `❌ Không tìm thấy kết quả nào phù hợp với từ khóa <b>${escapeHtml(searchText)}</b>`,
    parse_mode: "HTML" } }];
}

const formatTask = (task, index) => {
  const link = `https://t.me/${botUsername}?start=chitiet_${task.id}`;
  const onedrive = task.onedrive_link ? cleanLink(task.onedrive_link) : '';
  const clickupUrl = task.url ? cleanLink(task.url) : '';
  return (
`<b>${index + 1}.</b> <a href="${link}">${escapeHtml(task.name)}</a>
├ Trạng thái: ${escapeHtml(task.status) || 'Không rõ'}
├ List: ${task.list_name ? escapeHtml(task.list_name) : 'Không rõ'}
${onedrive ? `├ 📁 <a href="${onedrive}">Xem OneDrive</a>\n` : ''}└ 🔗 <a href="${clickupUrl}">Xem trong ClickUp</a>`
  );
};

// total_count lay tu COUNT(*) OVER() trong query - la con so CHINH XAC, khong bi anh huong boi LIMIT
const totalCount = all.length > 0 ? Number(all[0].total_count) : 0;
const shown = all; // da gioi han LIMIT 10 san trong query
const hasMore = totalCount > shown.length;

const header = hasMore
  ? `🔍 <b>Kết quả tìm kiếm: ${escapeHtml(searchText)}</b>\nTìm thấy <b>${totalCount}</b> kết quả phù hợp, hiển thị ${shown.length} kết quả gần đúng nhất:`
  : `🔍 <b>Kết quả tìm kiếm: ${escapeHtml(searchText)}</b>\nTìm thấy ${totalCount} kết quả:`;

const taskBlocks = shown.map((task, i) => formatTask(task, i));

// Fallback nếu quá dài (giới hạn Telegram sendMessage: 4096 ký tự) — bớt dần task hiển thị
// từ cuối danh sách cho tới khi vừa, không cắt giữa 1 block để tránh vỡ thẻ HTML.
const MAX_LEN = 3900;
let cutCount = 0;
function buildText(blocks, extraCut) {
  const lines = [header, ...blocks];
  if (extraCut > 0) {
    lines.push(`💡 Đã rút gọn bớt ${extraCut} kết quả do tin nhắn quá dài — nhập từ khóa cụ thể hơn để thu hẹp kết quả.`);
  } else if (hasMore) {
    lines.push(`💡 Còn ${totalCount - shown.length} kết quả khác chưa hiển thị — vui lòng nhập từ khóa cụ thể hơn để thu hẹp kết quả.`);
  }
  return lines.join('\n\n');
}
let blocks = taskBlocks.slice();
let text = buildText(blocks, cutCount);
while (text.length > MAX_LEN && blocks.length > 1) {
  blocks.pop();
  cutCount++;
  text = buildText(blocks, cutCount);
}

return [{ json: { chatId, text, parse_mode: "HTML" } }];

const chatId = $('Phân tích lệnh').first().json.chatId;
const taskRows = $('task_detail_sql').all().map(i => i.json).filter(t => t && t.id);
const linkRows = $input.all().map(i => i.json).filter(r => r && r.order_task_id);
const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cleanLink = (l) => (l || '').replace(/^'+|'+$/g, '').replace(/[{}]/g, '').trim();
const botUsername = $('⚙️ Config').first().json.botUsername;

if (taskRows.length === 0) {
  return [{ json: { chatId, text: '❌ Không tìm thấy task này.', parse_mode: 'HTML' } }];
}
const task = taskRows[0];

function linkBlock(label, emoji, url) {
  const u = escapeHtml(cleanLink(url));
  return `<b><a href="${u}">${emoji} ${label}</a></b>\n<code>${u}</code>`;
}

const blocks = [];
blocks.push(`<b>${escapeHtml(task.name)}</b>`);
blocks.push(`<b>Mô tả:</b>\n${escapeHtml(task.description?.trim()) || 'Không rõ'}`);
blocks.push(`<b>Trạng thái:</b>\n${escapeHtml(task.status) || 'Không rõ'}`);
blocks.push(`<b>List:</b>\n${task.list_name ? escapeHtml(task.list_name) : 'Không rõ'}`);
if (task.phu_trach) blocks.push(`<b>Phụ trách:</b>\n${escapeHtml(task.phu_trach)}`);
if (task.youtube_link) blocks.push(linkBlock('Youtube', '🎬', task.youtube_link));
if (task.onedrive_link) blocks.push(linkBlock('OneDrive', '📁', task.onedrive_link));
if (task.url) blocks.push(linkBlock('ClickUp', '🔗', task.url));

function groupByYear(rows) {
  const byYear = {};
  rows.forEach(r => {
    const y = r.year || 'khác';
    if (!byYear[y]) byYear[y] = [];
    byYear[y].push(r);
  });
  return byYear;
}
function renderGroup(label, byYear) {
  const out = [];
  for (const [year, rows] of Object.entries(byYear)) {
    const items = rows.map(r => {
      const link = `https://t.me/${botUsername}?start=chitiet_${r.order_task_id}`;
      return `• <a href="${link}">${escapeHtml(r.order_task_name)}</a> (${escapeHtml(r.order_task_status) || 'không rõ'})`;
    }).join('\n');
    out.push(`<b>${label} ${year} (${rows.length}):</b>\n${items}`);
  }
  return out;
}

const dkpvByYear = groupByYear(linkRows.filter(r => r.link_type === 'dkpv'));
const pvtcByYear = groupByYear(linkRows.filter(r => r.link_type === 'pvtc'));
blocks.push(...renderGroup('📝 Đăng ký phỏng vấn (DKPV)', dkpvByYear));
blocks.push(...renderGroup('✅ Phỏng vấn thành công (PVTC)', pvtcByYear));

const MAX_LEN = 3900;
function build(arr, cutCount) {
  const notice = cutCount > 0
    ? `\n\n⚠️ <i>(Nội dung quá dài, đã rút gọn ${cutCount} mục — xem đầy đủ trong ClickUp)</i>`
    : '';
  return arr.join('\n\n') + notice;
}
let arr = blocks.slice();
let cutCount = 0;
let text = build(arr, cutCount);
while (text.length > MAX_LEN && arr.length > 1) {
  arr.pop();
  cutCount++;
  text = build(arr, cutCount);
}

return [{ json: { chatId, text, parse_mode: 'HTML' } }];

// Cau hinh chung cho workflow - doi 1 dong nay khi cutover sang bot PROD (Giai doan 4, xem PROJECT_STATUS.md)
const USE_PROD_BOT = true; // false = dang dung bot DEV (test) | true = da cutover, dung bot PROD

const config = {
  botUsername: USE_PROD_BOT ? 'Elite_clickup_bot' : 'elite_n8n_test_bot',
  ADMIN_CHAT_ID: '975005174', // dung chung voi Gateway/Live Update - doi neu can
};

return [{ json: { ...$json, ...config } }];
